// The existing single-edit API works. Preserve it while extending this module.
import {readFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {realpathSync} from 'node:fs';
function checkEdit(source,edit){
  if(typeof source!=='string'||edit===null||typeof edit!=='object'||Array.isArray(edit)
    ||!Number.isSafeInteger(edit.start)||!Number.isSafeInteger(edit.end)
    ||edit.start<0||edit.start>edit.end||edit.end>source.length
    ||typeof edit.before!=='string'||typeof edit.after!=='string')throw Error('invalid edit');
  if(source.slice(edit.start,edit.end)!==edit.before)throw Error('preimage mismatch');
}
export function applyEdit(source,edit){
  checkEdit(source,edit);
  return source.slice(0,edit.start)+edit.after+source.slice(edit.end);
}
function conflicts(a,b){
  const aIns=a.start===a.end,bIns=b.start===b.end;
  if(aIns&&bIns)return a.start===b.start;
  if(aIns)return a.start>=b.start&&a.start<=b.end;
  if(bIns)return b.start>=a.start&&b.start<=a.end;
  return a.start<b.end&&b.start<a.end;
}
export function applyTransaction(source,edits){
  if(typeof source!=='string')throw Error('source must be a string');
  if(!Array.isArray(edits))throw Error('edits must be an array');
  const plan=[];
  for(let i=0;i<edits.length;i++){
    const e=edits[i];
    checkEdit(source,e);
    plan.push({index:i,start:e.start,end:e.end,after:e.after});
  }
  // Sort by start, insertions first at equal start so overlap checks between
  // neighbours are exhaustive; ties otherwise keep input order.
  plan.sort((a,b)=>a.start-b.start||a.end-b.end||a.index-b.index);
  for(let i=1;i<plan.length;i++){
    // Compare against all earlier edits that could still reach this one.
    for(let j=i-1;j>=0;j--){
      if(plan[j].end<plan[i].start)break;
      if(conflicts(plan[i],plan[j]))throw Error('conflicting edits');
    }
  }
  let out='',pos=0;
  for(const p of plan){
    out+=source.slice(pos,p.start)+p.after;
    pos=p.end;
  }
  out+=source.slice(pos);
  return {text:out,applied:plan.length};
}
export function runCli(argv){
  if(argv.length!==1)throw Error('usage: node patch-transaction.js INPUT_JSON_FILE');
  let data;
  try{data=JSON.parse(readFileSync(argv[0],'utf8'));}
  catch(e){throw Error('cannot read input: '+(e&&e.message||e));}
  if(data===null||typeof data!=='object'||Array.isArray(data))throw Error('input must be a JSON object');
  return applyTransaction(data.source,data.edits);
}
function isMain(){
  try{
    const arg=process.argv[1];
    return !!arg&&realpathSync(arg)===realpathSync(fileURLToPath(import.meta.url));
  }catch{return false;}
}
if(isMain()){
  try{
    const result=runCli(process.argv.slice(2));
    process.stdout.write(JSON.stringify(result)+'\n');
  }catch(e){
    process.stderr.write(String(e&&e.message||e)+'\n');
    process.exitCode=2;
  }
}
