import test from 'node:test';
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {mkdtempSync,writeFileSync,rmSync} from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {applyTransaction} from '../patch-transaction.js';
const edit=(start,end,before,after)=>({start,end,before,after});
const cli=path.join(path.dirname(fileURLToPath(import.meta.url)),'..','patch-transaction.js');

test('insertion rules',()=>{
  assert.throws(()=>applyTransaction('ab',[edit(1,1,'','x'),edit(1,1,'','')]),Error);
  assert.throws(()=>applyTransaction('abcd',[edit(1,3,'bc','x'),edit(2,2,'','y')]),Error);
  assert.throws(()=>applyTransaction('abcd',[edit(1,3,'bc','x'),edit(1,1,'','y')]),Error);
  assert.deepEqual(applyTransaction('abcd',[edit(1,3,'bc','x'),edit(0,0,'','y'),edit(4,4,'','z')]),{text:'yaxdz',applied:3});
});
test('overlap and no-op edits',()=>{
  assert.throws(()=>applyTransaction('abcd',[edit(0,2,'ab','x'),edit(1,3,'bc','y')]),Error);
  assert.throws(()=>applyTransaction('abcd',[edit(0,4,'abcd','x'),edit(1,3,'bc','y')]),Error);
  assert.deepEqual(applyTransaction('abcd',[edit(1,2,'b','b'),edit(3,4,'d','d')]),{text:'abcd',applied:2});
  assert.throws(()=>applyTransaction('ab',[edit(0,1,'a','x'),edit(0,1,'a','x')]),Error);
});
test('does not mutate input and rejects bad shapes',()=>{
  const edits=[edit(3,5,'de','X'),edit(0,1,'a','L')];
  const snapshot=JSON.stringify(edits);
  applyTransaction('abcdef',edits);
  assert.equal(JSON.stringify(edits),snapshot);
  assert.throws(()=>applyTransaction('abc',null),Error);
  assert.throws(()=>applyTransaction('abc',[null]),Error);
  assert.throws(()=>applyTransaction('abc',[edit('0',1,'a','x')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(0,1,'a','x'),edit(2,4,'c','y')]),Error);
});
test('cli success and failure',()=>{
  const dir=mkdtempSync(path.join(os.tmpdir(),'ptx-'));
  try{
    const ok=path.join(dir,'ok.json');
    writeFileSync(ok,JSON.stringify({source:'abc\r\n',edits:[edit(1,2,'b','B')],extra:1}));
    let r=spawnSync(process.execPath,[cli,ok],{encoding:'utf8'});
    assert.equal(r.status,0);
    assert.equal(r.stderr,'');
    assert.equal(r.stdout,JSON.stringify({text:'aBc\r\n',applied:1})+'\n');
    const bad=path.join(dir,'bad.json');
    writeFileSync(bad,'{nope');
    for(const args of [[],[ok,ok],[path.join(dir,'missing.json')],[bad]]){
      r=spawnSync(process.execPath,[cli,...args],{encoding:'utf8'});
      assert.equal(r.status,2);
      assert.equal(r.stdout,'');
      assert.ok(r.stderr.length>0);
    }
    const conflict=path.join(dir,'conflict.json');
    writeFileSync(conflict,JSON.stringify({source:'ab',edits:[edit(0,0,'','x'),edit(0,0,'','y')]}));
    r=spawnSync(process.execPath,[cli,conflict],{encoding:'utf8'});
    assert.equal(r.status,2);
    assert.equal(r.stdout,'');
  }finally{rmSync(dir,{recursive:true,force:true});}
});
